sys_ws_operation.operation_script:
// RBAC Authorization Check
(function() {
  if (gs.hasRole("admin")) return;
  var roles = "x_2056099_indust_0.production_supervisor,x_2056099_indust_0.production_manager,x_2056099_indust_0.production_planner,x_2056099_indust_0.plant_manager,x_2056099_indust_0.operations_manager".split(",");
  for (var _i = 0; _i < roles.length; _i++) {
    if (gs.hasRole(roles[_i])) return;
  }
  response.setStatus(403);
  response.setBody({error:"Unauthorized",message:"Insufficient role for this operation"});
})();
if (response.getStatus() == 403) { /* early exit */ }
else
(function process(request, response) {
  // API execution flag for lifecycle guard BR
  gs.getSession().putClientData("x_2056099_indust_0_api_transition", "cancel");

  var PO_TABLE = "x_2056099_indust_0_production_order";

  var body = {};
  try {
    body = JSON.parse(request.body.dataString);
  } catch (e) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Invalid request body" } });
    return;
  }

  var sysId = body.sys_id;
  if (!sysId) {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "sys_id is required" } });
    return;
  }

  var gr = new GlideRecord(PO_TABLE);
  if (!gr.get(sysId)) {
    response.setStatus(404);
    response.setBody({ result: { success: false, error: "Production Order not found" } });
    return;
  }

  if (gr.getValue("active") != "1") {
    response.setStatus(400);
    response.setBody({ result: { success: false, error: "Production Order is inactive and cannot be cancelled" } });
    return;
  }

  var currentStatus = gr.getValue("status");
  var previousStatusDisplay = gr.getDisplayValue("status");
  var cancellableStatuses = ["draft", "planned", "material_check", "materials_reserved", "on_hold"];
  var allowed = false;
  for (var i = 0; i < cancellableStatuses.length; i++) {
    if (cancellableStatuses[i] == currentStatus) { allowed = true; break; }
  }

  if (!allowed) {
    response.setStatus(400);
    response.setBody({
      result: {
        success: false,
        error: "Cannot cancel a Production Order with status '" + previousStatusDisplay + "'. Only Draft, Planned, Material Check, Materials Reserved, or On Hold orders can be cancelled."
      }
    });
    return;
  }

  gr.setValue("status", "cancelled");
  gr.update();

  response.setBody({
    result: {
      success: true,
      message: "Production Order cancelled. Previous status: " + previousStatusDisplay,
      record: {
        sys_id: gr.getValue("sys_id"),
        number: gr.getValue("number") || gr.getValue("sys_id"),
        status: gr.getValue("status"),
        statusDisplay: gr.getDisplayValue("status")
      }
    }
  });
})(request, response);
